<template>
  <div class="dashboard">
    <section class="hero"><div><p>GALLERY INTELLIGENCE CENTER</p><h1>图库运营驾驶舱</h1><span>从内容质量、采集节奏、版本健康度到检索来源，一屏定位值得处理的数据。</span></div><div><small>{{ lastUpdated ? '更新于 ' + lastUpdated : '正在加载' }}</small><el-button :icon="Refresh" plain @click="loadData">刷新数据</el-button></div></section>
    <el-card class="filters" shadow="never"><b><el-icon><Filter /></el-icon>分析范围</b><el-radio-group v-model="filters.days" @change="loadData"><el-radio-button :label="7">近 7 天</el-radio-button><el-radio-button :label="30">近 30 天</el-radio-button><el-radio-button :label="90">近 90 天</el-radio-button><el-radio-button :label="0">全部时间</el-radio-button></el-radio-group><el-select v-model="filters.status" clearable placeholder="全部下载状态" @change="loadData"><el-option v-for="x in STATUS_OPTIONS" :key="x.value" :label="x.label" :value="x.value"/></el-select><el-button text type="primary" @click="reset">重置筛选</el-button></el-card>
    <el-row :gutter="16" class="metrics"><el-col v-for="m in metrics" :key="m.label" :xs="12" :sm="8" :lg="4"><div class="metric" :class="m.tone"><el-icon><component :is="m.icon"/></el-icon><div><strong>{{ m.value }}</strong><small>{{ m.label }}</small></div></div></el-col></el-row>
    <el-row :gutter="16" class="row"><el-col :xs="24" :xl="15"><el-card class="panel"><template #header><Head title="采集趋势" sub="按日观察数据流入节奏"/></template><div ref="timelineRef" class="chart tall"/></el-card></el-col><el-col :xs="24" :xl="9"><el-card class="panel"><template #header><Head title="状态健康度" sub="下载与入库进度分布"/></template><div ref="statusRef" class="chart tall"/></el-card></el-col></el-row>
    <el-row :gutter="16" class="row"><el-col :xs="24" :lg="8"><el-card class="panel"><template #header><Head title="内容评分" sub="社区评分分层"/></template><div ref="ratingRef" class="chart"/></el-card></el-col><el-col :xs="24" :lg="8"><el-card class="panel"><template #header><Head title="篇幅结构" sub="作品页数分布"/></template><div ref="pagesRef" class="chart"/></el-card></el-col><el-col :xs="24" :lg="8"><el-card class="panel"><template #header><Head title="版本治理" sub="首选与重复版本占比"/></template><div ref="dedupeRef" class="chart"/></el-card></el-col></el-row>
    <el-row :gutter="16" class="row"><el-col :xs="24" :lg="10"><el-card class="panel"><template #header><Head title="检索来源 Top 8" sub="哪些关键词带来最多采集记录"/></template><div ref="queryRef" class="chart"/></el-card></el-col><el-col :xs="24" :lg="14"><el-card class="panel"><template #header><Head title="实时任务与数据服务" sub="当前下载队列和存储服务状态"/></template><div class="service"><span><i :class="dbStatus.connected ? 'ok' : 'error'"/>数据库{{ dbStatus.connected ? '连接正常' : '连接异常' }}</span><span>累计 {{ dbStatus.total ?? '-' }} 条 · {{ dbStatus.totalSizeGb ?? '-' }} GB</span></div><div v-if="downloads.length" class="tasks"><div v-for="x in downloads" :key="x.gid" class="task"><div><b>{{ x.title }}</b><small>#{{ x.gid }} · {{ bytes(x.downloadedBytes) }} / {{ bytes(x.totalBytes) }}</small></div><el-progress :percentage="x.percent" :stroke-width="8"/></div></div><el-empty v-else description="暂无进行中的下载任务" :image-size="70"/></el-card></el-col></el-row>
  </div>
</template>
<script setup>
import { computed, h, markRaw, onMounted, onUnmounted, ref } from 'vue'
import * as echarts from 'echarts'
import { DataAnalysis, Files, Filter, FolderChecked, Refresh, StarFilled, Tickets, WarningFilled } from '@element-plus/icons-vue'
import api from '../api'
import { STATUS_OPTIONS, getStatusMeta } from '../constants/status'
const filters=ref({days:30,status:''}),analytics=ref({overview:{},status:[],timeline:[],rating:[],pages:[],dedupe:[],queries:[]}),downloads=ref([]),dbStatus=ref({}),lastUpdated=ref('')
const timelineRef=ref(),statusRef=ref(),ratingRef=ref(),pagesRef=ref(),dedupeRef=ref(),queryRef=ref();let charts=[],timer
const Head=p=>h('div',{class:'head'},[h('b',p.title),h('small',p.sub)])
const metrics=computed(()=>{const o=analytics.value.overview||{};return [{label:'范围内画廊',value:o.total??'-',icon:markRaw(Files),tone:'blue'},{label:'内容体积',value:o.size_mb?(o.size_mb/1024).toFixed(1)+' GB':'0 GB',icon:markRaw(DataAnalysis),tone:'violet'},{label:'平均评分',value:o.avg_rating?Number(o.avg_rating).toFixed(2):'-',icon:markRaw(StarFilled),tone:'amber'},{label:'平均页数',value:o.avg_pages?Math.round(o.avg_pages):'-',icon:markRaw(Tickets),tone:'cyan'},{label:'重复版本',value:o.duplicates??0,icon:markRaw(WarningFilled),tone:'red'},{label:'活跃下载',value:downloads.value.length,icon:markRaw(FolderChecked),tone:'green'}]})
const base={textStyle:{fontFamily:'Inter, PingFang SC, Microsoft YaHei'},tooltip:{trigger:'axis'},grid:{left:42,right:18,top:24,bottom:38,containLabel:true}},order=(rows,names)=>names.map(name=>rows.find(x=>x.name===name)||({name,value:0}))
function pie(c,data,transform=x=>x){c.setOption({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['42%','70%'],center:['50%','45%'],label:{formatter:'{b}\\n{d}%'},itemStyle:{borderColor:'#fff',borderWidth:3,borderRadius:6},data:data.map(transform)}]},true)}
function bar(c,data,color,horizontal=false){c.setOption({...base,grid:{left:horizontal?105:28,right:18,top:20,bottom:horizontal?20:42,containLabel:true},xAxis:horizontal?{type:'value',splitLine:{lineStyle:{color:'#edf0f5'}}}:{type:'category',data:data.map(x=>x.name),axisLabel:{interval:0,color:'#7c8799'}},yAxis:horizontal?{type:'category',data:data.map(x=>x.name),axisLabel:{width:90,overflow:'truncate'}}:{type:'value',splitLine:{lineStyle:{color:'#edf0f5'}}},series:[{type:'bar',data:data.map(x=>x.value),itemStyle:{color,borderRadius:horizontal?[0,6,6,0]:[6,6,0,0]},barMaxWidth:30}]},true)}
function render(){const d=analytics.value,line=d.timeline||[];charts[0].setOption({...base,xAxis:{type:'category',data:line.map(x=>x.date),boundaryGap:false},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf0f5'}}},series:[{type:'line',data:line.map(x=>x.value),smooth:true,symbol:'none',lineStyle:{color:'#356dff',width:3},areaStyle:{color:'rgba(53,109,255,.2)'}}]},true);pie(charts[1],d.status,x=>({...x,name:getStatusMeta(x.name).label,itemStyle:{color:getStatusMeta(x.name).color}}));pie(charts[2],order(d.rating||[],['未评分','0–3','3–4','4–4.5','4.5–5']));bar(charts[3],order(d.pages||[],['未知','<20页','20–49页','50–99页','100页+']),'#20b6c7');pie(charts[4],d.dedupe,x=>({...x,itemStyle:{color:x.name==='重复版本'?'#f59e0b':'#4f8cff'}}));bar(charts[5],[...(d.queries||[])].reverse(),'#7c5cff',true)}
async function loadData(){try{const params={days:filters.value.days};if(filters.value.status)params.status=filters.value.status;const[a,d,db]=await Promise.all([api.get('/dashboard/analytics',{params}),api.get('/dashboard/download-progress'),api.get('/dashboard/db-status')]);analytics.value=a.data;downloads.value=d.data||[];dbStatus.value=db.data||{};lastUpdated.value=new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date());render()}catch{}}
function reset(){filters.value={days:30,status:''};loadData()}function bytes(v){const b=Number(v)||0;return b<1048576?(b/1024).toFixed(0)+' KB':b<1073741824?(b/1048576).toFixed(1)+' MB':(b/1073741824).toFixed(2)+' GB'}
function resize(){charts.forEach(x=>x.resize())}onMounted(()=>{charts=[timelineRef,statusRef,ratingRef,pagesRef,dedupeRef,queryRef].map(x=>echarts.init(x.value));loadData();timer=setInterval(loadData,30000);window.addEventListener('resize',resize)});onUnmounted(()=>{clearInterval(timer);window.removeEventListener('resize',resize);charts.forEach(x=>x.dispose())})
</script>
<style scoped>
.dashboard{padding:4px 0 20px;color:#1e293b}.hero{min-height:136px;padding:25px 30px;border-radius:16px;color:#fff;display:flex;justify-content:space-between;align-items:center;gap:20px;background:radial-gradient(circle at 85% 10%,#668cff 0,transparent 30%),linear-gradient(120deg,#15264e,#263d78);box-shadow:0 12px 28px rgba(32,55,116,.18)}.hero p{margin:0 0 6px;font-size:11px;font-weight:700;letter-spacing:.12em;color:#a8c1ff}.hero h1{font-size:27px;margin:0}.hero span{display:block;margin-top:8px;color:#cbd8fa;font-size:14px}.hero>div:last-child{display:flex;align-items:center;gap:12px}.hero small{color:#cbd8fa}.filters{margin:16px 0;border:0;border-radius:12px}.filters :deep(.el-card__body){display:flex;align-items:center;gap:16px;padding:12px 18px;flex-wrap:wrap}.filters b{display:flex;gap:6px}.filters .el-select{width:155px}.metrics{margin-bottom:16px}.metrics>*,.row>*{margin-bottom:12px}.metric{min-height:94px;padding:18px;background:#fff;border-radius:12px;display:flex;gap:13px;align-items:center;border:1px solid #eef1f6}.metric>.el-icon{height:42px;width:42px;border-radius:12px;display:grid;place-items:center;font-size:21px}.metric strong,.metric small{display:block}.metric strong{font-size:22px}.metric small{color:#7d8798;font-size:12px;margin-top:5px}.blue>.el-icon{background:#e8efff;color:#356dff}.violet>.el-icon{background:#f0ebff;color:#7656e8}.amber>.el-icon{background:#fff4dc;color:#e99b11}.cyan>.el-icon{background:#e5f9fb;color:#0aa3b4}.red>.el-icon{background:#fff0f0;color:#ed5c66}.green>.el-icon{background:#e8f8ee;color:#20a65a}.panel{height:100%;border:0;border-radius:12px}.panel :deep(.el-card__header){border-bottom:1px solid #f0f2f6;padding:15px 19px}.panel :deep(.el-card__body){padding:12px 19px 18px}.head{display:flex;justify-content:space-between}.head small{color:#98a1b1;font-size:12px;font-weight:400}.chart{height:245px}.tall{height:300px}.service{background:#f7f9fc;border-radius:8px;padding:11px 13px;display:flex;justify-content:space-between;color:#667085;font-size:13px}.service i{display:inline-block;height:7px;width:7px;border-radius:50%;margin-right:6px}.ok{background:#22c55e;box-shadow:0 0 0 3px #dcfce7}.error{background:#ef4444;box-shadow:0 0 0 3px #fee2e2}.tasks{max-height:175px;overflow:auto}.task{display:grid;grid-template-columns:minmax(0,1fr) 160px;gap:18px;align-items:center;padding:12px 2px;border-bottom:1px solid #f1f3f7}.task b,.task small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.task b{font-size:13px}.task small{margin-top:4px;color:#9098a6;font-size:11px}@media(max-width:768px){.hero{padding:22px;align-items:flex-start;flex-direction:column}.hero h1{font-size:23px}.head small{display:none}.task{grid-template-columns:1fr;gap:7px}}
</style>
